use sequence

record Progress
prior:?{Event} breaks:i current:i longest:i

advance state_value:{Progress} incoming:{Event} > {Progress}
let backward case (get prior state_value) false previous (earlier incoming previous)
let count if backward 0 (+ (get current state_value) 1)
let peak get longest state_value
make Progress prior (some incoming) breaks (+ (get breaks state_value) (if backward 1 0))
  current count longest (if (> count peak) count peak)
